use std::cell::RefCell;

thread_local! {
    // Thread-private block pool cache to avoid global allocation lock
    static LOCAL_BLOCK_POOL: RefCell<Vec<Vec<u8>>> = RefCell::new(Vec::new());
}

pub fn allocate_block() -> Vec<u8> {
    LOCAL_BLOCK_POOL.with(|pool| {
        pool.borrow_mut().pop().unwrap_or_else(|| vec![0; 4096])
    })
}

pub fn free_block(block: Vec<u8>) {
    LOCAL_BLOCK_POOL.with(|pool| {
        pool.borrow_mut().push(block);
    })
}
